module wireless_coverage (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] N,\n    input wire [3:0] M,\n    input wire [7:0] K,\n    input wire [7:0] cost00, cost01, cost02, cost03,\n    input wire [7:0] cost10, cost11, cost12, cost13,\n    input wire [7:0] cost20, cost21, cost22, cost23,\n    input wire [7:0] cost30, cost31, cost32, cost33,\n    output reg [15:0] result,\n    output reg done\n);\n\n    // State definitions\n    localparam [2:0] IDLE    = 3'd0;\n    localparam [2:0] INIT    = 3'd1;\n    localparam [2:0] CALC    = 3'd2;\n    localparam [2:0] COMPARE = 3'd3;\n    localparam [2:0] INCR    = 3'd4;\n    localparam [2:0] DONE_ST = 3'd5;\n    \n    localparam [15:0] HUGE_PENALTY = 16'd10000;\n    \n    // Internal registers\n    reg [2:0] state, next_state;\n    reg [15:0] counter;\n    reg [15:0] min_cost;\n    reg [15:0] router_sum;\n    reg [15:0] edge_sum;\n    reg [15:0] conf;\n    reg [3:0] row_idx, col_idx;\n    reg phase;\n    reg edge_type;\n    reg [7:0] cost_reg [0:15];\n    \n    // Valid mask calculation\n    reg [15:0] valid_mask;\n    always @(*) begin\n        case (N * M)\n            4'd1: valid_mask = 16'h0001;\n            4'd2: valid_mask = 16'h0003;\n            4'd3: valid_mask = 16'h0007;\n            4'd4: valid_mask = 16'h000F;\n            4'd5: valid_mask = 16'h001F;\n            4'd6: valid_mask = 16'h003F;\n            4'd7: valid_mask = 16'h007F;\n            4'd8: valid_mask = 16'h00FF;\n            4'd9: valid_mask = 16'h01FF;\n            4'd10: valid_mask = 16'h03FF;\n            4'd11: valid_mask = 16'h07FF;\n            4'd12: valid_mask = 16'h0FFF;\n            4'd13: valid_mask = 16'h1FFF;\n            4'd14: valid_mask = 16'h3FFF;\n            4'd15: valid_mask = 16'h7FFF;\n            default: valid_mask = 16'hFFFF;\n        endcase\n    end\n\n    // Position calculation wire\n    wire [3:0] pos;\n    assign pos = (row_idx * M) + col_idx;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 16'd0;\n            counter <= 16'd0;\n            min_cost <= 16'hFFFF;\n            router_sum <= 16'd0;\n            edge_sum <= 16'd0;\n            conf <= 16'd0;\n            row_idx <= 4'd0;\n            col_idx <= 4'd0;\n            phase <= 1'b0;\n            edge_type <= 1'b0;\n            // Initialize cost_reg array\n            cost_reg[0] <= 8'd0; cost_reg[1] <= 8'd0; cost_reg[2] <= 8'd0; cost_reg[3] <= 8'd0;\n            cost_reg[4] <= 8'd0; cost_reg[5] <= 8'd0; cost_reg[6] <= 8'd0; cost_reg[7] <= 8'd0;\n            cost_reg[8] <= 8'd0; cost_reg[9] <= 8'd0; cost_reg[10] <= 8'd0; cost_reg[11] <= 8'd0;\n            cost_reg[12] <= 8'd0; cost_reg[13] <= 8'd0; cost_reg[14] <= 8'd0; cost_reg[15] <= 8'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        cost_reg[0] <= cost00; cost_reg[1] <= cost01;\n                        cost_reg[2] <= cost02; cost_reg[3] <= cost03;\n                        cost_reg[4] <= cost10; cost_reg[5] <= cost11;\n                        cost_reg[6] <= cost12; cost_reg[7] <= cost13;\n                        cost_reg[8] <= cost20; cost_reg[9] <= cost21;\n                        cost_reg[10] <= cost22; cost_reg[11] <= cost23;\n                        cost_reg[12] <= cost30; cost_reg[13] <= cost31;\n                        cost_reg[14] <= cost32; cost_reg[15] <= cost33;\n                        state <= INIT;\n                    end\n                end\n                \n                INIT: begin\n                    router_sum <= 16'd0;\n                    edge_sum <= 16'd0;\n                    conf <= counter;\n                    row_idx <= 4'd0;\n                    col_idx <= 4'd0;\n                    phase <= 1'b0;\n                    state <= CALC;\n                end\n                \n                CALC: begin\n                    if (!phase) begin  // Router sum phase\n                        if (row_idx < N) begin\n                            if (col_idx < M) begin\n                                if (conf[pos]) begin\n                                    router_sum <= router_sum + cost_reg[pos];\n                                end\n                                col_idx <= col_idx + 4'd1;\n                            end else begin\n                                row_idx <= row_idx + 4'd1;\n                                col_idx <= 4'd0;\n                            end\n                        end else begin\n                            if (conf & ~valid_mask) begin\n                                router_sum <= router_sum + HUGE_PENALTY;\n                            end\n                            phase <= 1'b1;\n                            row_idx <= 4'd0;\n                            col_idx <= 4'd0;\n                            edge_type <= 1'b0;\n                        end\n                    end else begin    // Edge sum phase\n                        if (!edge_type) begin  // Horizontal edges\n                            if (row_idx < N) begin\n                                if (col_idx < (M - 1)) begin\n                                    if (conf[(row_idx*M)+col_idx] == conf[(row_idx*M)+col_idx+1]) begin\n                                        edge_sum <= edge_sum + K;\n                                    end\n                                    col_idx <= col_idx + 4'd1;\n                                end else begin\n                                    row_idx <= row_idx + 4'd1;\n                                    col_idx <= 4'd0;\n                                end\n                            end else begin\n                                edge_type <= 1'b1;\n                                row_idx <= 4'd0;\n                                col_idx <= 4'd0;\n                            end\n                        end else begin         // Vertical edges\n                            if (row_idx < (N - 1)) begin\n                                if (col_idx < M) begin\n                                    if (conf[(row_idx*M)+col_idx] == conf[((row_idx+1)*M)+col_idx]) begin\n                                        edge_sum <= edge_sum + K;\n                                    end\n                                    col_idx <= col_idx + 4'd1;\n                                end else begin\n                                    row_idx <= row_idx + 4'd1;\n                                    col_idx <= 4'd0;\n                                end\n                            end else begin\n                                state <= COMPARE;\n                            end\n                        end\n                    end\n                end\n                \n                COMPARE: begin\n                    if ((router_sum + edge_sum) < min_cost) begin\n                        min_cost <= router_sum + edge_sum;\n                    end\n                    state <= INCR;\n                end\n                \n                INCR: begin\n                    counter <= counter + 16'd1;\n                    if (counter == 16'hFFFF) state <= DONE_ST;\n                    else state <= INIT;\n                end\n                \n                DONE_ST: begin\n                    result <= min_cost;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule